source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    points = {}
    for r in range(h):
        for c in range(w):
            if out[r][c]:
                points.setdefault(out[r][c], []).append((r, c))

    def put(r, c, value):
        if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
            out[r][c] = value

    for r, c in points.get(1, []):
        put(r, c + 1, 5)
        put(r, c + 2, 5)
        put(r - 1, c + 2, 1)
    for r, c in points.get(2, []):
        put(r, c - 1, 5)
        put(r, c - 2, 5)
        put(r, c - 3, 5)
        put(r, c - 4, 2)
    for r, c in points.get(3, []):
        put(r + 1, c, 5)
        put(r + 2, c, 5)
        put(r + 3, c, 3)
    for r, c in points.get(6, []):
        for d in range(1, 6):
            put(r - d, c, 5)
        put(r - 6, c, 6)

    # Where the horizontal 2-ray crosses a vertical 3/6-ray, mark the
    # crossing and the down-left diagonal in color 4.
    for r2, c2 in points.get(2, []):
        for color in (3, 6):
            for rv, cv in points.get(color, []):
                if abs(c2 - cv) > 4:
                    continue
                if color == 3 and not (rv <= r2 <= rv + 3):
                    continue
                if color == 6 and not (rv - 6 <= r2 <= rv):
                    continue
                if out[r2][cv] == 0 or out[r2][cv] == 5:
                    out[r2][cv] = 4
                rr, cc = r2 + 1, cv - 1
                while rr < h and cc >= 0:
                    if out[rr][cc] == 0:
                        out[rr][cc] = 4
                    rr += 1
                    cc -= 1
    return out
'''
